<?php
/**
 * API Backend for Arduino Bioresonance Controller
 * 
 * Handles TCP communication with Arduino Nano, session management,
 * and provides a JSON API for the WebUI frontend.
 * 
 * @version 2.0 (Security & Stability Hardened)
 * @author Generated by AI
 */

// --- KONFIGURACJA ---
define('DEBUG_MODE', false);
define('LOG_FILE', __DIR__ . '/debug.log');
define('LOCK_FILE', __DIR__ . '/session.lock');
define('LOCK_TIMEOUT', 30); // Sekundy po których lock jest uznawany za osierocony
define('MAX_LOG_SIZE', 1048576); // 1MB limit dla pliku logów
define('DEFAULT_ARDUINO_IP', '192.168.4.1');
define('DEFAULT_ARDUINO_PORT', 23);

// The WebUI sends JSON bodies; PHP does not populate $_POST for application/json.
if (($_SERVER['CONTENT_TYPE'] ?? '') !== '' &&
    stripos($_SERVER['CONTENT_TYPE'], 'application/json') !== false) {
    $requestBody = file_get_contents('php://input');
    $decodedBody = json_decode($requestBody, true);
    if (is_array($decodedBody)) {
        $_POST = array_merge($_POST, $decodedBody);
    }
}

// Inicjalizacja sesji PHP
if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

// Nagłówki bezpieczeństwa i JSON
header('Content-Type: application/json; charset=utf-8');
header('X-Content-Type-Options: nosniff');
header('X-Frame-Options: DENY');

// --- FUNKCJE POMOCNICZE ---

/**
 * Rejestruje funkcję sprzątającą na wypadek nagłego zakończenia skryptu
 */
function register_socket_cleanup(&$socket) {
    register_shutdown_function(function() use (&$socket) {
        if (is_resource($socket) || ($socket instanceof \Socket)) {
            debug_log("SHUTDOWN: Forced socket close due to script termination.");
            @socket_close($socket);
        }
    });
}

/**
 * Bezpieczna funkcja logowania z rotacją pliku
 */
function debug_log($message, $level = 'INFO') {
    if (!DEBUG_MODE) return;

    // Rotacja logu jeśli za duży
    if (file_exists(LOG_FILE) && filesize(LOG_FILE) > MAX_LOG_SIZE) {
        $oldContent = file_get_contents(LOG_FILE);
        // Zachowaj tylko ostatnią połowę pliku
        $lines = explode("\n", $oldContent);
        $lines = array_slice($lines, count($lines) / 2);
        file_put_contents(LOG_FILE, implode("\n", $lines));
    }

    $timestamp = date('Y-m-d H:i:s');
    $logLine = "[$timestamp] [$level] $message\n";
    file_put_contents(LOG_FILE, $logLine, FILE_APPEND | LOCK_EX);
}

/**
 * Zwraca odpowiedź JSON i kończy skrypt
 */
function json_response($success, $data = null, $error = null) {
    echo json_encode([
        'success' => $success,
        'data' => $data,
        'error' => $error,
        'timestamp' => time()
    ]);
    exit;
}

/**
 * Walidacja adresu IP
 */
function validate_ip($ip) {
    if (!is_string($ip) || filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) === false) return false;
    $value = ip2long($ip);
    if ($value === false) return false;
    $ranges = [
        ['10.0.0.0', '10.255.255.255'],
        ['172.16.0.0', '172.31.255.255'],
        ['192.168.0.0', '192.168.255.255']
    ];
    foreach ($ranges as [$start, $end]) {
        if ($value >= ip2long($start) && $value <= ip2long($end)) return true;
    }
    return false;
}

/**
 * Walidacja portu
 */
function validate_port($port) {
    if (!is_scalar($port) || !preg_match('/^[0-9]{1,5}$/', (string)$port)) return false;
    $p = (int)$port;
    return $p >= 1 && $p <= 65535;
}

function require_api_token() {
    $expected = getenv('BIORESONANCE_API_TOKEN');
    $provided = $_SERVER['HTTP_X_BIORESONANCE_TOKEN'] ?? '';
    if (!is_string($expected) || strlen($expected) < 32 ||
        !is_string($provided) || !hash_equals($expected, $provided)) {
        json_response(false, null, 'Unauthorized: configure BIORESONANCE_API_TOKEN and send X-Bioresonance-Token');
    }
}

/**
 * Escapowanie znaków specjalnych do safe command
 */
function sanitize_command($cmd) {
    // Usuń znaki nowej linii, aby zapobiec injekcjom wieloliniowym
    return preg_replace('/[\r\n]+/', '', trim($cmd));
}

// --- OBSŁUGA BLOKAD (LOCKING) ---

/**
 * Acquires a session lock with stale-lock detection
 */
function acquire_lock() {
    // Never unlink a lock file based on age: that can split synchronization
    // across two inodes and permit concurrent operations.
    $fp = fopen(LOCK_FILE, 'c+');
    if (!$fp) {
        return false;
    }

    if (!flock($fp, LOCK_EX | LOCK_NB)) {
        fclose($fp);
        return false;
    }
    
    // Zapisz PID procesu w locku dla debugowania
    ftruncate($fp, 0);
    fwrite($fp, json_encode(['pid' => getmypid(), 'time' => time()]));
    fflush($fp);
    
    return $fp;
}

function release_lock($fp) {
    if ($fp) {
        flock($fp, LOCK_UN);
        fclose($fp);
    }
}

// --- KOMUNIKACJA TCP Z ARDUINO ---

/**
 * Łączy się z Arduino, wysyła komendę i odbiera odpowiedź
 * 
 * @param string $command Komenda do wysłania
 * @param string $ip Adres IP Arduino
 * @param int $port Port TCP
 * @return array Wynik operacji
 */
function send_to_arduino($command, $ip, $port) {
    $socket = null;
    $timeout_sec = 2;
    $timeout_usec = 500000;

    debug_log("TCP: Connecting to $ip:$port");

    // 1. Tworzenie socketu
    $socket = socket_create(AF_INET, SOCK_STREAM, SOL_TCP);
    if ($socket === false) {
        $err = socket_last_error();
        $msg = socket_strerror($err);
        debug_log("TCP: Create failed - $msg ($err)", "ERROR");
        return ['success' => false, 'error' => "Socket create failed: $msg"];
    }

    // Rejestracja sprzątania
    register_socket_cleanup($socket);

    // 2. Ustawienie timeoutów
    if (!socket_set_option($socket, SOL_SOCKET, SO_RCVTIMEO, ['sec' => $timeout_sec, 'usec' => $timeout_usec])) {
        debug_log("TCP: Failed to set receive timeout", "WARN");
    }
    if (!socket_set_option($socket, SOL_SOCKET, SO_SNDTIMEO, ['sec' => $timeout_sec, 'usec' => $timeout_usec])) {
        debug_log("TCP: Failed to set send timeout", "WARN");
    }

    // 3. Łączenie
    $result = @socket_connect($socket, $ip, $port);
    if ($result === false) {
        $err = socket_last_error($socket);
        $msg = socket_strerror($err);
        debug_log("TCP: Connect failed - $msg ($err)", "ERROR");
        socket_close($socket);
        return ['success' => false, 'error' => "Connection failed: $msg (Check IP/Port/Arduino)"];
    }

    debug_log("TCP: Connected successfully");

    // 4. Wysyłanie danych
    // Dodajemy newline na koniec komendy jeśli go nie ma (protokół tekstowy)
    if (substr($command, -1) !== "\n") {
        $command .= "\n";
    }
    
    $totalLength = strlen($command);
    $offset = 0;
    while ($offset < $totalLength) {
        $bytesSent = @socket_write($socket, substr($command, $offset), $totalLength - $offset);
        if ($bytesSent === false || $bytesSent === 0) {
            $err = socket_last_error($socket);
            $msg = socket_strerror($err);
            debug_log("TCP: Write failed after $offset/$totalLength bytes - $msg", "ERROR");
            socket_close($socket);
            return ['success' => false, 'error' => "Send failed: $msg"];
        }
        $offset += $bytesSent;
    }
    debug_log("TCP: Sent $offset bytes: " . trim($command));

    // 5. Odbieranie odpowiedzi
    $response = "";
    while ($out = socket_read($socket, 2048)) {
        if ($out === false) {
            // Check if it's just a timeout (no data) or real error
            $err = socket_last_error($socket);
            if ($err != SOCKET_ETIMEDOUT && $err != SOCKET_EAGAIN) {
                 debug_log("TCP: Read error - " . socket_strerror($err), "ERROR");
            }
            break; 
        }
        $response .= $out;
        // Jeśli odpowiedź jest kompletna (np. kończy się newline), można przerwać wcześniej
        if (strpos($out, "\n") !== false) break;
    }

    debug_log("TCP: Received: " . trim($response));

    // 6. Zamykanie
    socket_close($socket);
    debug_log("TCP: Connection closed");

    return [
        'success' => true,
        'data' => trim($response),
        'raw_response' => $response
    ];
}

// --- GŁÓWNA LOGIKA API ---

$action = $_POST['action'] ?? $_GET['action'] ?? '';
$ip = $_POST['ip'] ?? $_SESSION['arduino_ip'] ?? DEFAULT_ARDUINO_IP;
$port = $_POST['port'] ?? $_SESSION['arduino_port'] ?? DEFAULT_ARDUINO_PORT;

// Validate every destination before any outbound socket operation.
// The WebUI is intended to reach a device on a private/local network only.
if (!validate_ip($ip) || !validate_port($port)) {
    json_response(false, null, 'Invalid device address or port; only private IPv4 targets are allowed.');
}

// Zapisz preferencje w sesji
$_SESSION['arduino_ip'] = $ip;
$_SESSION['arduino_port'] = (int)$port;

debug_log("API Request: action=$action, ip=$ip, port=$port");

switch ($action) {
    case 'connect_test':
        require_api_token();
        if (!validate_ip($ip)) {
            json_response(false, null, "Invalid IP address format");
        }
        if (!validate_port($port)) {
            json_response(false, null, "Invalid port number");
        }
        
        $result = send_to_arduino("STATUS\n", $ip, $port);
        if ($result['success']) {
            json_response(true, ['message' => 'Connected', 'response' => $result['data']]);
        } else {
            json_response(false, null, $result['error']);
        }
        break;

    case 'get_status':
        require_api_token();
        $fp = acquire_lock();
        if (!$fp) {
            json_response(false, null, "System busy (another operation in progress)");
        }
        
        try {
            $result = send_to_arduino("STATUS\n", $ip, $port);
            if ($result['success']) {
                // Parsowanie odpowiedzi (przykład: TEMP:30|MEM:50|UP:100)
                $parsed = [];
                $parts = explode('|', $result['data']);
                foreach($parts as $part) {
                    $kv = explode(':', $part);
                    if(count($kv) == 2) $parsed[trim($kv[0])] = trim($kv[1]);
                }
                json_response(true, $parsed);
            } else {
                json_response(false, null, $result['error']);
            }
        } finally {
            release_lock($fp);
        }
        break;

    case 'save_config':
        require_api_token();
        $channels = $_POST['channels'] ?? [];
        $mode = $_POST['mode'] ?? 'SINGLE';

        // Reject malformed values instead of coercing them into a different device command.
        if (!is_array($channels) || count($channels) === 0) {
            json_response(false, null, "No channel data provided");
        }
        if (!is_string($mode) || !in_array($mode, ['SINGLE', 'MULTI'], true)) {
            json_response(false, null, "Invalid configuration mode");
        }

        $validatedChannels = [];
        $seenIds = [];
        foreach ($channels as $index => $ch) {
            if (!is_array($ch)) {
                json_response(false, null, "Invalid channel at index " . (int)$index);
            }
            foreach (['id', 'name', 'type', 'freq', 'duty', 'intensity', 'modulation', 'enabled'] as $field) {
                if (!array_key_exists($field, $ch)) {
                    json_response(false, null, "Missing channel field: $field");
                }
            }

            foreach (['id', 'type', 'duty', 'intensity', 'modulation'] as $field) {
                if (!is_int($ch[$field]) &&
                    !(is_string($ch[$field]) && preg_match('/^[0-9]{1,5}$/D', $ch[$field]))) {
                    json_response(false, null, "Invalid integer field: $field");
                }
            }
            $id = (int)$ch['id'];
            $type = (int)$ch['type'];
            $duty = (int)$ch['duty'];
            $intens = (int)$ch['intensity'];
            $mod = (int)$ch['modulation'];

            if ($id > 65535 || isset($seenIds[$id]) ||
                $type > 65535 || $duty > 100 || $intens > 255 || $mod > 65535) {
                json_response(false, null, "Channel field out of range or duplicate channel id");
            }
            $seenIds[$id] = true;

            if (!is_string($ch['name']) || strlen($ch['name']) > 20 ||
                preg_match('/[|\x00-\x1F\x7F]/', $ch['name'])) {
                json_response(false, null, "Invalid channel name (max 20 bytes; delimiters/control characters are forbidden)");
            }
            if ((!is_int($ch['freq']) && !is_float($ch['freq']) &&
                 !(is_string($ch['freq']) && is_numeric($ch['freq']))) ||
                !is_finite((float)$ch['freq']) || (float)$ch['freq'] < 0) {
                json_response(false, null, "Invalid channel frequency");
            }
            if (!in_array($ch['enabled'], [true, false, 0, 1, '0', '1'], true)) {
                json_response(false, null, "Invalid channel enabled flag");
            }

            $validatedChannels[] = [
                'id' => $id, 'name' => $ch['name'], 'type' => $type,
                'freq' => (float)$ch['freq'], 'duty' => $duty,
                'intensity' => $intens, 'modulation' => $mod,
                'enabled' => in_array($ch['enabled'], [true, 1, '1'], true) ? 1 : 0
            ];
        }

        $fp = acquire_lock();
        if (!$fp) {
            json_response(false, null, "System busy");
        }

        try {
            $configString = "CONFIG MODE:$mode\n";
            foreach ($validatedChannels as $ch) {
                $configString .= "CH:{$ch['id']}|{$ch['name']}|{$ch['type']}|{$ch['freq']}|{$ch['duty']}|{$ch['intensity']}|{$ch['modulation']}|{$ch['enabled']}\n";
            }
            $configString .= "END_CONFIG\n";
            if (strlen($configString) > 65536) {
                json_response(false, null, "Configuration payload exceeds 64 KiB");
            }

            debug_log("Sending bulk config...");
            $result = send_to_arduino($configString, $ip, $port);
            
            if ($result['success']) {
                json_response(true, ['message' => 'Configuration saved', 'details' => $result['data']]);
            } else {
                json_response(false, null, "Failed to save config: " . $result['error']);
            }

        } finally {
            release_lock($fp);
        }
        break;

    case 'control':
        require_api_token();
        $subAction = $_POST['sub'] ?? ''; // START, STOP, PAUSE
        
        if (!in_array($subAction, ['START', 'STOP', 'PAUSE'])) {
            json_response(false, null, "Invalid control command");
        }

        $fp = acquire_lock();
        if (!$fp) {
            json_response(false, null, "System busy");
        }

        try {
            $cmd = $subAction . "\n";
            $result = send_to_arduino($cmd, $ip, $port);
            
            if ($result['success']) {
                json_response(true, ['message' => "$subAction command sent", 'response' => $result['data']]);
            } else {
                json_response(false, null, $result['error']);
            }
        } finally {
            release_lock($fp);
        }
        break;

    case 'raw_command':
        json_response(false, null, 'Raw commands are disabled; use explicitly validated API operations.');
        break;

    default:
        json_response(false, null, "Unknown action: $action");
        break;
}
?>
